'use strict';
const $=id=>document.getElementById(id);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let state='idle',level=0,skin='ghost',apiBase='',apiToken='',connected=false,busy=false,motion=reduced,matrixOn=false,epoch=0;
let previewTimer=null,previewMode=false;
let mediaStream=null,audioContext=null,analyser=null,recognition=null,audioElement=null,objectURL=null,currentAbort=null;
const states={idle:['GOTOWOŚĆ','Oczekuję na polecenie.','STANDBY / 01'],listening:['NASŁUCH','Odbieram sygnał głosowy.','LISTENING / 02'],thinking:['ANALIZA','Przetwarzam zapytanie.','PROCESSING / 03'],speaking:['ODPOWIEDŹ','Przekazuję odpowiedź.','TRANSMITTING / 04'],error:['UWAGA','Sprawdź komunikat w rozmowie.','ATTENTION / 05'],connecting:['ŁĄCZĘ','Szukam Twojego Lakiego.','CONNECTING / 06']};
function setState(s,hint){state=s;document.body.dataset.state=s;$('ghost').dataset.state=s;$('ghost').setAttribute('aria-label','Laki — holograficzna sylwetka, stan: '+(states[s]?.[0]||s).toLowerCase());const [label,message,code]=states[s]||states.idle;$('state-label').textContent=label;$('core-message').textContent=message;$('core-code').textContent=code;$('halo').dataset.state=s;$('core-hint').textContent=hint||(s==='idle'?'Napisz wiadomość lub włącz mikrofon.':'');const colors={idle:'#a4c5c4',listening:'#a3d9cd',thinking:'#c4b693',speaking:'#a8c8dd',error:'#d7a2a7',connecting:'#b5b2cc'};document.documentElement.style.setProperty('--cyan',colors[s]||colors.idle)}
function eventLog(title,detail=''){const e=document.createElement('div');e.className='event';const i=document.createElement('i'),body=document.createElement('div'),small=document.createElement('small');body.textContent=title;small.textContent=detail||new Date().toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});body.append(small);e.append(i,body);$('activity').prepend(e);while($('activity').children.length>4)$('activity').lastElementChild.remove()}
function addMessage(role,text,note=''){const article=document.createElement('article');article.className='message '+role;const author=document.createElement('div');author.className='message-author';author.textContent=role==='user'?'TY':'◈ LAKI';const t=document.createElement('span');t.textContent=new Date().toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});author.append(t);const p=document.createElement('p');p.textContent=text;article.append(author,p);if(note){const small=document.createElement('small');small.textContent=note;article.append(small)}$('chat-log').append(article);$('chat-log').scrollTop=$('chat-log').scrollHeight}
function setBusy(value){busy=value;$('chat-form').querySelector('button').disabled=value;$('mic').disabled=value;document.querySelectorAll('[data-prompt]').forEach(b=>b.disabled=value);$('welcome').disabled=value}
function cleanupAudio(){if(recognition){const r=recognition;recognition=null;r.onend=null;r.onerror=null;r.abort()}if(mediaStream){mediaStream.getTracks().forEach(t=>t.stop());mediaStream=null}if(audioElement){audioElement.pause();audioElement.onended=null;audioElement=null}if(objectURL){URL.revokeObjectURL(objectURL);objectURL=null}if(audioContext){audioContext.close().catch(()=>{});audioContext=null}analyser=null;level=0;$('mic-state').textContent='Wyłączony';$('mic').querySelector('span').textContent='Rozpocznij rozmowę';$('signal').textContent='SYGNAŁ AUDIO —'}
function stopAll(){clearTimeout(previewTimer);previewMode=false;document.querySelectorAll('[data-preview]').forEach(b=>b.setAttribute('aria-pressed','false'));epoch++;currentAbort?.abort();currentAbort=null;cleanupAudio();window.speechSynthesis?.cancel();setBusy(false);setState('idle');eventLog('Zatrzymano rozmowę')}
$('stop').onclick=stopAll;
function speak(text){cleanupAudio();if(!$('voice-toggle').checked||!('speechSynthesis' in window)){setState('idle');return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='pl-PL';const voice=window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('pl'));if(voice)u.voice=voice;u.rate=.98;const e=epoch;u.onstart=()=>{if(e!==epoch)return;setState('speaking','Głos przeglądarki • animacja stanu mówienia');$('signal').textContent='TTS / BEZ ANALIZY AMPLITUDY'};u.onend=()=>{if(e!==epoch)return;setState('idle');$('signal').textContent='SYGNAŁ AUDIO —'};u.onerror=ev=>{if(e!==epoch||ev.error==='interrupted'||ev.error==='canceled')return;setState('idle','Głos niedostępny. Odpowiedź jest w rozmowie.');eventLog('Nie udało się odtworzyć głosu',ev.error)};window.speechSynthesis.speak(u)}
function demoReply(text){if(/stan|status|system/i.test(text))return 'Interfejs jest uruchomiony, ale nie mam połączenia z serwerem Lakiego. Otwórz „Połączenie”, aby sprawdzić /health i odczytać /status. Nie pokazuję przykładowych statystyk jako rzeczywistych danych.';if(/potraf|możliwości/i.test(text))return 'Interfejs Lakiego prezentuje stan nasłuchu, analizy i odpowiedzi w postaci holograficznej sylwetki. Dostępne są rozmowa tekstowa, wejście głosowe, analiza pliku audio oraz adapter połączenia z API. Możesz zmienić wygląd, włączyć Matrix, przetestować mikrofon i wczytać plik audio. Po podłączeniu API odpowiedzi będzie dostarczał Twój Laki.';if(/cześć|witaj|hej/i.test(text))return 'Cześć, jestem Laki. Jak mogę Ci pomóc?';return 'To podgląd interfejsu Lakiego. Twoja wiadomość nie została wysłana do modelu AI. Aby otrzymywać prawdziwe odpowiedzi z Twojego systemu, skonfiguruj połączenie z API.'}
async function apiRequest(path,options={},timeout=20000){const controller=new AbortController();currentAbort=controller;const timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(apiBase+path,{...options,signal:controller.signal,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(apiToken?{Authorization:'Bearer '+apiToken}:{}),...options.headers}});if(!response.ok)throw Error('HTTP '+response.status);return await response.json()}finally{clearTimeout(timer);if(currentAbort===controller)currentAbort=null}}
function extractReply(data){if(typeof data==='string')return data;for(const key of ['response','reply','answer','message','text'])if(typeof data?.[key]==='string')return data[key];if(typeof data?.response?.text==='string')return data.response.text;throw Error('Odpowiedź /chat nie zawiera tekstu. Dopasuj adapter extractReply w app.js do schematu Lakiego.')}
async function send(text){text=text.trim();if(!text||busy)return;clearTimeout(previewTimer);previewMode=false;document.querySelectorAll('[data-preview]').forEach(b=>b.setAttribute('aria-pressed','false'));epoch++;const e=epoch;cleanupAudio();window.speechSynthesis?.cancel();addMessage('user',text);$('prompt').value='';setBusy(true);setState('thinking',connected?'Oczekuję na odpowiedź Twojego Lakiego.':'Podgląd zachowania interfejsu • bez modelu AI');try{let reply;if(connected){reply=extractReply(await apiRequest('/chat',{method:'POST',body:JSON.stringify({message:text})},60000))}else{await new Promise(resolve=>setTimeout(resolve,motion?20:650));reply=demoReply(text)}if(e!==epoch)return;addMessage('assistant',reply,connected?'Odpowiedź API Lakiego':'Odpowiedź demonstracyjna');eventLog(connected?'Odpowiedź od Lakiego':'Test interfejsu',connected?'POST /chat':'Tryb demonstracyjny');speak(reply)}catch(err){if(e!==epoch)return;setState('error');addMessage('assistant','Nie udało się pobrać odpowiedzi: '+err.message,'Sprawdź adres API, CORS i schemat /chat.');eventLog('Błąd połączenia',err.message)}finally{if(e===epoch)setBusy(false)}}
$('chat-form').onsubmit=e=>{e.preventDefault();send($('prompt').value)};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>send(b.dataset.prompt));$('welcome').onclick=()=>{stopAll();const text='Cześć, jestem Laki. Jak mogę Ci pomóc?';addMessage('assistant',text,'Próba głosu przeglądarki');speak(text)};
$('clear-chat').onclick=()=>{$('chat-log').replaceChildren();eventLog('Wyczyszczono widok rozmowy')};
function configure(){ $('config-feedback').textContent='';$('api-url').value=apiBase;$('config').showModal() }$('settings').onclick=configure;$('connect-open').onclick=configure;$('close-config').onclick=()=>$('config').close();
$('demo').onclick=()=>{stopAll();connected=false;apiBase='';apiToken='';$('api-token').value='';$('api-state').textContent='Niepołączony';$('connection').textContent='TRYB DEMONSTRACYJNY';$('system-title').textContent='Gotowy do podłączenia';$('system-description').textContent='Interfejs działa w przeglądarce. Serwer Lakiego nie jest połączony.';$('status-json').textContent='Brak połączenia z serwerem.';$('config').close();eventLog('Włączono tryb demonstracyjny')};
$('config-form').onsubmit=async e=>{e.preventDefault();if(busy)return;stopAll();let url;try{url=new URL($('api-url').value);if(!['https:','http:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)throw Error('Podaj sam adres API, bez hasła, zapytania i fragmentu.');if(location.protocol==='https:'&&url.protocol!=='https:')throw Error('Ten podgląd działa przez HTTPS. API również musi udostępniać HTTPS.')}catch(err){$('config-feedback').textContent=err.message;return}apiBase=url.href.replace(/\/$/,'');apiToken=$('api-token').value;connected=false;setBusy(true);const eId=epoch;const button=e.submitter;button.disabled=true;$('config-feedback').textContent='Sprawdzam /health…';setState('connecting');try{const health=await apiRequest('/health');if(eId!==epoch)return;connected=true;$('api-state').textContent='Połączony';$('connection').textContent='POŁĄCZONO Z LAKIM';$('system-title').textContent='Twój Laki jest dostępny';$('system-description').textContent='Serwer odpowiada na /health. Rozmowy będą wysyłane do /chat.';let status;try{status=await apiRequest('/status')}catch(err){status={health,status_error:err.message}}if(eId!==epoch)return;$('status-json').textContent=JSON.stringify(status,null,2);$('config-feedback').textContent='Połączono. /chat wymaga zgodnego schematu.';$('config').close();setState('idle');eventLog('Połączono z API Lakiego',url.host)}catch(err){if(eId!==epoch)return;connected=false;$('api-state').textContent='Błąd';$('connection').textContent='BRAK POŁĄCZENIA';$('system-title').textContent='Połączenie niedostępne';$('system-description').textContent='Sprawdź serwer, adres API i CORS. Rozmowa pozostaje w trybie demonstracyjnym.';$('status-json').textContent='Brak aktualnego statusu: '+err.message;$('config-feedback').textContent='Nie udało się połączyć: '+err.message;setState('error');eventLog('API niedostępne',err.message)}finally{button.disabled=false;if(eId===epoch)setBusy(false)}};
$('mic').onclick=async()=>{if(state==='listening'){cleanupAudio();setState('idle');return}stopAll();const e=epoch;const SR=window.SpeechRecognition||window.webkitSpeechRecognition;try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Ta przeglądarka nie udostępnia mikrofonu. Użyj pola tekstowego.');mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});if(e!==epoch){cleanupAudio();return}audioContext=new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();analyser=audioContext.createAnalyser();analyser.fftSize=256;audioContext.createMediaStreamSource(mediaStream).connect(analyser);$('mic-state').textContent='Aktywny';$('mic').querySelector('span').textContent='Zakończ słuchanie';$('signal').textContent='MIKROFON / PRAWDZIWA AMPLITUDA';setState('listening',SR?'Rozpoznawanie pl-PL zależy od przeglądarki i może korzystać z usługi online.':'Mikrofon reaguje na dźwięk. Transkrypcja niedostępna — wpisz wiadomość.');eventLog('Mikrofon włączony','Awatar reaguje na rzeczywisty dźwięk');if(SR){recognition=new SR();recognition.lang='pl-PL';recognition.interimResults=false;recognition.continuous=false;recognition.onresult=ev=>{const text=ev.results[0][0].transcript;cleanupAudio();setState('idle');send(text)};recognition.onerror=ev=>{if(e!==epoch)return;cleanupAudio();setState('error','Rozpoznawanie mowy: '+ev.error);eventLog('Transkrypcja niedostępna',ev.error)};recognition.onend=()=>{if(state==='listening'){cleanupAudio();setState('idle')}};recognition.start()}}catch(err){cleanupAudio();setState('error','Mikrofon niedostępny. Możesz napisać wiadomość.');addMessage('assistant','Nie mogę włączyć mikrofonu: '+err.message);eventLog('Mikrofon niedostępny',err.name)}};
$('audio-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;stopAll();const id=epoch;try{audioContext=new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();if(id!==epoch)return;analyser=audioContext.createAnalyser();analyser.fftSize=256;audioElement=new Audio();objectURL=URL.createObjectURL(file);audioElement.src=objectURL;audioContext.createMediaElementSource(audioElement).connect(analyser);analyser.connect(audioContext.destination);audioElement.onended=()=>{cleanupAudio();setState('idle')};await audioElement.play();setState('speaking','Awatar reaguje na rzeczywistą amplitudę pliku audio.');$('signal').textContent='PLIK AUDIO / PRAWDZIWA AMPLITUDA';eventLog('Odtwarzanie audio',file.name)}catch(err){cleanupAudio();setState('error','Nie udało się odtworzyć tego pliku audio.');eventLog('Błąd odtwarzania',err.message)}finally{e.target.value=''}};
$('voice-toggle').onchange=()=>{if(!$('voice-toggle').checked){window.speechSynthesis?.cancel();if(state==='speaking'&&!audioElement)setState('idle')}};
document.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{skin=b.dataset.skin;document.body.dataset.skin=skin;$('ghost').hidden=skin!=='ghost';$('halo').hidden=skin!=='halo';$('reactor').hidden=skin!=='reactor';document.querySelectorAll('[data-skin]').forEach(x=>x.classList.toggle('active',x===b));eventLog('Zmieniono rdzeń',skin==='ghost'?'Laki / Holograficzna sylwetka':skin==='halo'?'VoiceOrbs / Halo':'JARVIS / Reaktor')});
$('matrix-toggle').onchange=e=>{matrixOn=e.target.checked;$('matrix').style.display=matrixOn?'block':'none'};$('motion-toggle').checked=motion;document.body.classList.toggle('reduce-motion',motion);$('motion-toggle').onchange=e=>{motion=e.target.checked;document.body.classList.toggle('reduce-motion',motion)};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));$('system-detail').hidden=b.dataset.view!=='system';if(b.dataset.view==='conversation'){$('prompt').focus();$('chat-form').scrollIntoView({behavior:motion?'instant':'smooth',block:'center'})}if(b.dataset.view==='system')$('system-detail').scrollIntoView({behavior:motion?'instant':'smooth',block:'center'})});
for(let i=0;i<10;i++){const winding=document.createElement('i');winding.style.transform=`rotate(${i*36}deg) translateY(-100px)`;$('windings').append(winding)}
function clock(){const now=new Date();$('clock').textContent=now.toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});$('date').textContent=now.toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}clock();setInterval(clock,1000);$('tts-state').textContent='speechSynthesis' in window?'Przeglądarka':'Niedostępna';
const ctx=$('sphere').getContext('2d'),wave=$('wave').getContext('2d'),matrix=$('matrix').getContext('2d');let drops=[];function resize(){const dpr=Math.min(devicePixelRatio||1,2);$('sphere').width=450;$('sphere').height=450;$('matrix').width=Math.floor(innerWidth*dpr);$('matrix').height=Math.floor(innerHeight*dpr);matrix.setTransform(dpr,0,0,dpr,0,0);drops=Array.from({length:Math.ceil(innerWidth/22)},()=>Math.random()*innerHeight/20)}resize();addEventListener('resize',resize);
const samples=new Uint8Array(256);let last=0;function draw(t){requestAnimationFrame(draw);if(document.hidden||t-last<40)return;last=t;if(analyser){analyser.getByteTimeDomainData(samples);let sum=0;for(const x of samples)sum+=((x-128)/128)**2;level=Math.min(1,Math.sqrt(sum/samples.length)*4)}else level*=.8;const mouth=state==='speaking'?(analyser?level:(motion?.35:Math.max(.08,Math.sin(t*.018)*Math.sin(t*.027)*.65+.2))):0;$('ghost').style.setProperty('--mouth',mouth.toFixed(3));$('ghost').style.setProperty('--energy',level.toFixed(3));$('reactor').style.setProperty('--level',level.toFixed(3));$('halo').style.setProperty('--orb-level',level.toFixed(3));ctx.clearRect(0,0,450,450);const angle=motion?0:t*.0001;ctx.fillStyle='#8bf0ed';for(let i=0;i<420;i++){const y=1-2*i/419,r=Math.sqrt(1-y*y),a=i*2.399963+angle;const x=Math.cos(a)*r,z=Math.sin(a)*r;const scale=1+level*.1;ctx.globalAlpha=.12+(z+1)*.25;ctx.beginPath();ctx.arc(225+x*82*scale,225+y*82*scale,Math.max(.6,(z+1)*.9),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;wave.clearRect(0,0,380,42);wave.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--cyan').trim();wave.lineWidth=1;wave.beginPath();for(let i=0;i<380;i++){const y=21+(analyser?(samples[Math.floor(i/380*256)]-128)*.6:Math.sin(i*.13)*(motion?0:1.2));i?wave.lineTo(i,y):wave.moveTo(i,y)}wave.stroke();if(matrixOn){if(motion){matrix.clearRect(0,0,innerWidth,innerHeight);matrix.fillStyle='#43986c';matrix.font='12px monospace';for(let i=0;i<drops.length;i++)matrix.fillText('01 ラキ',i*22,drops[i]*20)}else{matrix.fillStyle='rgba(7,16,20,.055)';matrix.fillRect(0,0,innerWidth,innerHeight);matrix.fillStyle='#68e6a7';matrix.font='12px monospace';drops.forEach((d,i)=>{matrix.fillText('01ラキシステム'[Math.floor(Math.random()*9)],i*22,d*20);drops[i]=d*20>innerHeight&&Math.random()>.98?0:d+.3})}}}requestAnimationFrame(draw);
document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{if(busy)return;stopAll();previewMode=true;document.querySelectorAll('[data-preview]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));setState(b.dataset.preview,'Podgląd stanu • mikrofon pozostaje wyłączony');$('signal').textContent='PODGLĄD REAKCJI / 5 S';previewTimer=setTimeout(()=>{previewMode=false;document.querySelectorAll('[data-preview]').forEach(x=>x.setAttribute('aria-pressed','false'));setState('idle');$('signal').textContent='SYGNAŁ AUDIO —'},5000)});
